    "9.1": [
      {"id":"wb-9.1-01","type":"mc","diff":1,"skill":"electrons-flow","source":"wb","lang":"en","q":"Electrons are found in all metal wires. What do they do when a current flows?","svg":null,"choices":["They flow around the circuit in one direction.","They vibrate more slowly.","They stop moving.","They keep moving randomly, as before."],"answer":0,"accept":[],"tol":0,"unitLabel":"","hints":["Dòng điện là gì: một dòng chảy có hướng hay chuyển động lung tung?","Khi chưa có dòng điện, electron tự do chuyển động thế nào?","Điều gì thay đổi khi mạch kín?"],"explain":"Khi có dòng điện, electron tự do chạy quanh mạch theo một chiều (từ cực âm về cực dương). Chuyển động hỗn loạn chỉ xảy ra khi không có dòng điện.","why":null,"howto":null},
      {"id":"wb-9.1-02","type":"mc","diff":1,"skill":"electron-charge","source":"wb","lang":"en","q":"Which statement about the free electrons in a metal wire is true?","svg":null,"choices":["They have a positive charge.","They have a negative charge.","They have no charge."],"answer":1,"accept":[],"tol":0,"unitLabel":"","hints":["Electron bị cực dương hay cực âm của pin hút?","Điện tích trái dấu thì hút nhau. Vậy electron mang điện gì?","Nếu electron không mang điện, cực của pin có hút hay đẩy được chúng không?"],"explain":"Electron tự do mang điện tích âm. Vì thế chúng bị cực dương hút và bị cực âm đẩy.","why":null,"howto":null},
      {"id":"wb-9.1-03","type":"mc","diff":2,"skill":"cell-terminals","source":"wb","lang":"en","q":"Complete the sentence: \"A cell has a ……… terminal and a ……… terminal.\"","svg":null,"choices":["positive … negative","positive … neutral","neutral … negative","north … south"],"answer":0,"accept":[],"tol":0,"unitLabel":"","hints":["Trên vỏ pin thường in hai kí hiệu nào ở hai đầu?","«Trung hòa» nghĩa là không mang điện. Một cực của pin có thể trung hòa không?","Bắc – nam là các cực của vật gì?"],"explain":"Pin có cực dương (+) và cực âm (−). «Bắc – nam» là cực của nam châm, không phải của pin.","why":null,"howto":null},
      {"id":"wb-9.1-04","type":"mc","diff":2,"skill":"electron-direction","source":"wb","lang":"en","q":"Complete the sentence: \"In a circuit, electrons flow away from the ……… terminal and towards the ……… terminal.\"","svg":null,"choices":["negative … positive","positive … negative","neutral … positive","negative … neutral"],"answer":0,"accept":[],"tol":0,"unitLabel":"","hints":["Electron mang điện âm. Cực âm đẩy hay hút electron?","Cực nào hút electron?","Electron rời khỏi cực đẩy nó và đi về cực hút nó."],"explain":"Cực âm đẩy electron ra, cực dương hút electron về, nên electron chạy từ cực âm qua mạch về cực dương.","why":null,"howto":null},
      {"id":"wb-9.1-05","type":"mc","diff":3,"skill":"arrows-terminal","source":"wb","lang":"en","q":"The arrows show the direction of electron flow in this circuit. The ends of the cell are labelled P and Q. Which end is the NEGATIVE terminal?","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 260 160\" stroke=\"currentColor\" fill=\"none\" stroke-width=\"1.5\"><line x1=\"50\" y1=\"35\" x2=\"112\" y2=\"35\"/><rect x=\"112\" y=\"26\" width=\"36\" height=\"18\"/><text x=\"130\" y=\"35.5\" fill=\"currentColor\" stroke=\"none\" font-size=\"10\" text-anchor=\"middle\" dominant-baseline=\"middle\">cell</text><text x=\"106\" y=\"21\" fill=\"currentColor\" stroke=\"none\" font-size=\"11\" text-anchor=\"middle\" dominant-baseline=\"middle\">P</text><text x=\"154\" y=\"21\" fill=\"currentColor\" stroke=\"none\" font-size=\"11\" text-anchor=\"middle\" dominant-baseline=\"middle\">Q</text><line x1=\"148\" y1=\"35\" x2=\"210\" y2=\"35\"/><line x1=\"210\" y1=\"35\" x2=\"210\" y2=\"125\"/><line x1=\"50\" y1=\"125\" x2=\"120\" y2=\"125\"/><circle cx=\"130\" cy=\"125\" r=\"10\"/><line x1=\"123\" y1=\"118\" x2=\"137\" y2=\"132\"/><line x1=\"123\" y1=\"132\" x2=\"137\" y2=\"118\"/><line x1=\"140\" y1=\"125\" x2=\"210\" y2=\"125\"/><line x1=\"50\" y1=\"35\" x2=\"50\" y2=\"125\"/><polygon fill=\"currentColor\" stroke=\"none\" points=\"210,86 205,76 215,76\"/><polygon fill=\"currentColor\" stroke=\"none\" points=\"79,125 89,120 89,130\"/><polygon fill=\"currentColor\" stroke=\"none\" points=\"50,74 45,84 55,84\"/></svg>","choices":["Q","P","both","neither"],"answer":0,"accept":[],"tol":0,"unitLabel":"","hints":["Theo mũi tên, electron đi RA khỏi pin ở đầu nào (đi xuống dây bên phải)?","Electron bị cực nào đẩy ra?","Đầu P nhận electron đi vào. Vậy P là cực gì?"],"explain":"Mũi tên cho thấy electron rời pin ở đầu Q, đi xuống, qua đèn rồi đi lên về đầu P. Electron bị cực âm đẩy ra nên Q là cực âm, P là cực dương.","why":null,"howto":null},
      {"id":"wb-9.1-06","type":"mc","diff":3,"skill":"cut-wire","source":"wb","lang":"en","q":"A lamp is lit in a circuit. Someone cuts the wire at a point far away from the lamp. Why does the lamp go out immediately?","svg":null,"choices":["Electrons can only flow in a complete circuit; the cut stops the flow everywhere at once.","The electrons leak out of the cut end.","The cell runs out of energy at that moment.","Only the electrons near the cut stop, and the lamp needs all of them."],"answer":0,"accept":[],"tol":0,"unitLabel":"","hints":["Sau khi cắt, vòng mạch có còn kín không?","Electron có thể nhảy qua khe hở không khí không?","Electron trong mạch nối tiếp chuyển động giống một đoàn tàu. Một toa dừng thì cả đoàn thế nào?"],"explain":"Vết cắt tạo chỗ hở; electron chỉ chạy được trong mạch kín nên toàn bộ dòng chảy ngừng cùng lúc, đèn tắt dù vết cắt ở xa.","why":null,"howto":null},
      {"id":"wb-9.1-07","type":"text","diff":2,"skill":"attract-word","source":"wb","lang":"en","q":"Complete the rule with one word: \"Opposite charges ……… each other.\"","svg":null,"choices":null,"answer":"attract","accept":["attracts","hút","hút nhau","pull","pull together"],"tol":0,"unitLabel":"","hints":["Điện tích cùng dấu thì đẩy nhau. Điện tích trái dấu thì ngược lại.","Cực dương làm gì với electron (mang điện âm)?","Từ tiếng Anh bắt đầu bằng «att…»."],"explain":"Điện tích trái dấu thì hút nhau (attract); cùng dấu thì đẩy nhau (repel).","why":null,"howto":null},
      {"id":"wb-9.1-08","type":"mc","diff":2,"skill":"random-motion","source":"wb","lang":"en","q":"A copper wire is lying on a table. It is NOT connected to anything. What are its free electrons doing?","svg":null,"choices":["moving about randomly, with no overall flow","not moving at all until a cell pushes them","all drifting slowly towards one end of the wire","slowly leaking out of the wire and escaping into the air"],"answer":0,"accept":[],"tol":0,"unitLabel":"","hints":["Electron «tự do» có nghĩa là chúng có thể làm gì trong kim loại?","Khi không có pin, có lực nào đẩy tất cả electron về cùng một phía không?","Nếu electron chạy lung tung mỗi hạt một hướng, có dòng chảy chung theo một chiều không?"],"explain":"Electron tự do luôn chuyển động hỗn loạn theo mọi hướng. Chỉ khi nối vào mạch có pin, chúng mới cùng chuyển động theo một chiều — đó mới là dòng điện.","why":null,"howto":null}
    ],
